export function metrics(attempts,profileId){const rows=attempts.filter(a=>a.childId===profileId);return {count:rows.length,completed:new Set(rows.map(a=>a.activityId)).size,guided:rows.filter(a=>a.mode==='guided'),free:rows.filter(a=>a.mode==='free'),scored:rows.filter(a=>typeof a.score==='number'&&!a.experimental),activeMs:rows.reduce((s,a)=>s+(a.visibleDurationMs||0),0)}}
